/// One button: what is written on it, what is spoken, its picture and its colour.
struct VocabItem: Identifiable, Hashable {
    let id: String
    let label: String
    let spoken: String
    let emoji: String
    /// The Fitzgerald Key colour, as 0xRRGGBB. Colour means the kind of word.
    let colour: UInt32
    /// The page this button opens, for a folder.
    let opens: String?
}

/// A page of buttons in a fixed grid. `order` holds each place in the grid, with nil for an empty one.
struct VocabBoard: Identifiable {
    let id: String
    let name: String
    let rows: Int
    let columns: Int
    let order: [[String?]]
    let items: [VocabItem]

    func item(_ id: String) -> VocabItem? { items.first { $0.id == id } }
}

/// A button that speaks straight away, such as Yes or I need a break.
struct QuickPhrase: Identifiable, Hashable {
    let id: String
    let label: String
    let spoken: String
}

